"""Build portable, offline review artifacts. Does not deploy or push source."""
from pathlib import Path
import json,csv,html,re,argparse
from model import ROOT,REPORT,DEFAULT,evaluate
OUT=ROOT/'outputs';esc=html.escape

def money(x):return 'Not defined' if x is None else f'${x:,.0f}'
def ratio(x):return 'No debt' if x is None else f'{x:.2f}x'
def table(headers,rows):return '<div class="scroll" role="region" aria-label="'+esc(headers[0]+' table')+'" tabindex="0"><table><thead><tr>'+''.join('<th scope="col">'+esc(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def svg(name):
 s=(OUT/(name+'.svg')).read_text();s=s[s.index('<svg'):];
 for old in set(re.findall(r'id="([^"]+)"',s)):
  new=name+'-'+old;s=s.replace('id="'+old+'"','id="'+new+'"').replace('href="#'+old+'"','href="#'+new+'"').replace('url(#'+old+')','url(#'+new+')')
 s=s.replace('<svg ',f'<svg role="img" aria-label="{name.replace("-"," ")}: hypothetical scenario analysis" ',1);return s

def main():
 parser=argparse.ArgumentParser();parser.add_argument('--release',action='store_true');args=parser.parse_args()
 r=evaluate(DEFAULT);s=r['steady'];register=list(csv.DictReader((ROOT/'data/assumption_register.csv').open()));meta={x['key']:x for x in register}
 pct={'eligible_traffic_share','capture_rate','store_margin','deli_margin','pizza_margin','lottery_commission','nonfuel_card_fee','payroll_load','contingency_rate','loan_to_cost','annual_interest_rate','loan_fee_rate','ramp_start','wash_margin'}
 selections={'report_scenario':[('low','Low report estimate'),('average','Average report estimate'),('high','High report estimate')],'scope':[('core','Core store + fuel'),('full','Core + hypothetical wash')],'fuel_source':[('report','Use report gallons'),('traffic','Use a hypothetical traffic funnel')]}
 specs={
 'lottery_commission':(5,100,.1),'sales_multiplier':(.0,5,.01),'aadt':(0,1000000,100),'eligible_traffic_share':(0,100,1),'capture_rate':(0,100,.1),'gallons_per_transaction':(0,100,1),'net_fuel_margin':(0,5,.01),
 'hours_open_per_day':(0,24,.5),'average_staff_on_duty':(0,20,.05),'hourly_wage':(0,500,.5),'fixed_opex_monthly':(0,1000000,500),'maintenance_reserve_monthly':(0,1000000,100),
 'land_cost':(0,100000000,10000),'hard_cost':(0,100000000,10000),'soft_cost':(0,100000000,10000),'working_capital':(0,100000000,10000),'amortization_years':(1,40,1),
 'target_dscr':(.1,5,.05),'construction_months':(1,60,1),'permit_delay_months':(0,36,1),'preopening_carry_monthly':(0,1000000,500),'ramp_months':(1,36,1),
 'wash_hard_cost':(0,100000000,10000),'wash_sales_monthly':(0,10000000,500),'wash_extra_labor_hours_monthly':(0,10000,10),'wash_maintenance_monthly':(0,1000000,100)}
 def field(k):
  m=meta[k];hint=m['basis'];label=m['label'];unit='%' if k in pct else m['unit'];scale=100 if k in pct else 1
  if k in selections:
   inp=f'<select id="input-{k}" data-key="{k}" aria-describedby="help-{k}">'+''.join(f'<option value="{v}"'+(' selected' if v==DEFAULT[k] else '')+'>'+esc(l)+'</option>' for v,l in selections[k])+'</select>'
  else:
   low,high,step=specs.get(k,(0,95 if k=='loan_to_cost' else 100,.1));inp=f'<input id="input-{k}" data-key="{k}" data-scale="{scale}" type="number" min="{low}" max="{high}" step="{step}" value="{DEFAULT[k]*scale:g}" required aria-describedby="help-{k}">'
  return f'<div class="field"><label for="input-{k}">{esc(label)} <span class="muted">({esc(unit)})</span></label>{inp}<small id="help-{k}">{esc(hint)}</small></div>'
 def group(title,keys,opened=False):return '<details'+(' open' if opened else '')+'><summary>'+esc(title)+'</summary><div class="fields">'+''.join(field(k) for k in keys)+'</div></details>'
 groups=[('Costs, financing and operating assumptions',['hard_cost','land_cost','loan_to_cost','annual_interest_rate','net_fuel_margin','store_margin','average_staff_on_duty','hourly_wage','fixed_opex_monthly','permit_delay_months','sales_multiplier','target_dscr'],True),('Other category margins and payment fees',['deli_margin','pizza_margin','lottery_commission','nonfuel_card_fee'],False),('Staffing, reserves and project capital',['hours_open_per_day','payroll_load','maintenance_reserve_monthly','soft_cost','contingency_rate','working_capital'],False),('Development draws, loan term and opening ramp',['amortization_years','loan_fee_rate','construction_months','preopening_carry_monthly','ramp_months','ramp_start'],False),('Fuel volume: report estimate or traffic scenario',['fuel_source','aadt','eligible_traffic_share','capture_rate','gallons_per_transaction'],False),('Incremental wash assumptions, active only in full scope',['wash_hard_cost','wash_sales_monthly','wash_margin','wash_extra_labor_hours_monthly','wash_maintenance_monthly'],False)]
 assert set(k for _,keys,_ in groups for k in keys)|{'report_scenario','scope'}==set(DEFAULT)
 gates=list(csv.DictReader((ROOT/'data/decision_gates.csv').open()));risks=json.loads((ROOT/'data/risk_register.json').read_text())
 gate_rows=table(['Evidence gate','Required evidence','Status'],[(x['gate'],x['required_evidence'],x['status']) for x in gates])
 mismatch_rows=table(['Risk','Reported label','Calculated score','Label under report rules'],[(x['description'],x['reported_band'],str(x['recomputed_score']),x['recomputed_band']) for x in risks if x['mismatch']])
 report_rows=table(['Report case','Fuel gallons / month','Store sales','Lottery ticket sales','Deli sales','Pizza sales','Nonfuel total'],[(k.title(),f'{v["fuel_gallons"]:,}',money(v['store_sales']),money(v['lottery_ticket_sales']),money(v['deli_sales']),money(v['pizza_sales']),money(v['reported_nonfuel_receipts'])) for k,v in REPORT['scenarios'].items()])
 source_text='''<p><strong>F01:</strong> User-supplied April 2026 investment decision memo. Revenue table p.1; traffic and demographics p.2; site program and recommendation p.4. <strong>R01:</strong> User-supplied risk assessment. Thresholds p.2; register pp.3-6; heat map p.7; construction discussion p.8; residual assertions pp.10-11. R01 references use an 11-page rendered copy and may differ in Word.</p><p>The original underlying feasibility study was not provided. Source estimates have not been independently validated as forecasts. Names, exact address, parcel identifiers and original files are withheld. Page references allow the owner to trace the extracts without redistributing the attachments.</p><p><strong>E01:</strong> <a href="https://fmcpa.cpa.state.tx.us/fiscalmoa/exp.jsp?num=7260" target="_blank" rel="noopener">Texas Comptroller, retailer commissions</a>: compensation is at least 5% of ticket sales. The model uses 5%, excludes bonuses and does not establish actual retailer terms. <strong>E02:</strong> <a href="https://www.tceq.texas.gov/downloads/assistance/publications/rg-475b.pdf/view" target="_blank" rel="noopener">TCEQ RG-475b, January 2024</a>: licensed installation and notification/registration requirements; pp.3-4 describe permitted materials and secondary containment. Fiberglass is not the only permitted tank material. <strong>E03:</strong> <a href="https://www.txdot.gov/data-maps/traffic-count-maps.html" target="_blank" rel="noopener">TxDOT traffic-count source</a>: identifies where counts can be checked; it does not verify this report’s count or capture rate. External pages retrieved 28 October 2026; source snapshots and hashes are retained in the prepared repository.</p>'''
 methods='''<h3>What the model does</h3><p>Start with a report sales case. Replace lottery face-value receipts with the assumed commission, apply category gross margins and card costs, add net fuel contribution, and deduct loaded staffing, fixed operating costs and maintenance reserves. This yields pre-tax cash available for debt service, not accounting net income.</p><p>Monthly debt service uses a fixed-rate amortizing loan on the selected debt share of acquisition, soft costs and construction including fully spent contingency. Development interest is paid by the sponsor on average monthly drawn balances. Acquisition and soft costs are paid at closing; hard costs draw evenly after any added permit delay. Pre-opening carry and loan fees are separate sponsor cash uses. No financing is assumed for these uses or working capital.</p><p>Operating sales ramp linearly while staffing and fixed costs start in full. Opening working capital means inventory and other working-capital investment, excluding the loss reserve. It is funded once. Peak sponsor funding adds the maximum cumulative operating deficit through 36 operating months; it is horizon-dependent, not lifetime funding needs. Monthly debt amortization continues during the operating period.</p><p>The financing-capacity ceiling solves for the eligible budget consistent with the selected stabilized coverage ratio at the assumed leverage and term. It is not fair value, an acquisition offer or a first-year coverage guarantee. Break-even fuel volume holds nonfuel contribution fixed. The all-sales threshold changes all categories together with fixed staffing. Both are algebraic scenarios, not demand forecasts.</p><h3>What is excluded</h3><p>Income taxes, depreciation, tax shields, terminal sale proceeds, appreciation, refinancing, prepayment, balloons, future working-capital changes and itemized fuel inventory float are excluded. No lender covenant, actual return, NPV or IRR is asserted. Category overlap, sales taxes, franchise fees and supplier/payment arrangements need source clarification or explicit cost allowances. A sales increase does not automatically prove unchanged staffing is achievable.</p><p>Risk scores remain subjective ordinal ratings. They are not failure probabilities, expected losses or simulation distributions. A corrected label does not validate the underlying rating, and a planned mitigation does not prove a lower residual risk.</p>'''
 css=(OUT/'app.css').read_text();basehead=f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>Fuel Retail Investment Decision Lab | Prathamesh Singh</title><style>{css}</style></head><body><a class="skip" href="#main">Skip to content</a><div class="wrap"><header class="topbar"><a class="brand" href="https://prathameshsingh.com">Prathamesh Singh <span aria-hidden="true">↗</span></a><span class="review-label">{('Anonymized independent research' if args.release else 'Private review files / Not published')}</span></header>'
 body=f'''<main id="main"><section class="hero"><div><p class="eyebrow">Finance / Development risk / Scenario analysis</p><h1>What would make this investment work?</h1><p class="lead">The reports estimate sales. This lab tests whether those sales could support an assumed fuel-retail development budget, operating plan and loan.</p><div class="hero-actions"><a class="small-link" href="#inputs">Change the assumptions ↓</a><a class="small-link" href="report.html">Read the analytical report ↗</a></div></div><aside class="hero-note" aria-label="Reference scenario coverage"><span class="note-label">Illustration, not actual performance</span><strong class="ratio" id="hero-ratio">{ratio(s['dscr'])}</strong><p id="hero-ratio-label">Stabilized coverage under the reference assumptions. Target 1.25x.</p></aside></section><nav class="subnav" aria-label="Research sections"><a href="#decision">Decision screen</a><a href="#inputs">Assumptions</a><a href="#cashflow">Cash and funding</a><a href="#evidence">Evidence</a><a href="#methods">Method</a></nav>
<section class="section" id="decision"><p class="eyebrow">01 / What the illustration says</p><h2 id="decision-heading">The reference illustration misses the coverage screen.</h2><p class="status" id="live-status" role="status" aria-live="polite" aria-atomic="true">Reference results loaded. Site-specific evidence remains unverified.</p><div class="metrics"><div class="metric"><b id="cash-metric">{money(s['cfads'])}</b><span>Stabilized monthly cash available for debt</span></div><div class="metric"><b id="debt-metric">{money(s['monthly_debt_service'])}</b><span>Modeled monthly debt payment</span></div><div class="metric"><b id="year1-metric">{ratio(r['year1_dscr'])}</b><span>Opening-year coverage after sales ramp</span></div><div class="metric"><b id="funding-metric">{money(r['peak_sponsor_funding_36m'])}</b><span>Peak sponsor funding through 36 operating months</span></div></div><div class="decision-copy"><p id="decision-explanation">The average report sales estimates produce {money(s['cfads'])} a month before debt under the reference cost assumptions. Debt service is {money(s['monthly_debt_service'])}. These are hypothetical underwriting results, not actual project performance.</p><p class="gate-line">Eight site-specific evidence gates remain unverified. Passing a numerical coverage screen does not establish site feasibility, investment value, financing approval or readiness to proceed.</p></div></section>
<section class="section" id="inputs"><div class="section-head"><div><p class="eyebrow">02 / Make every assumption visible</p><h2>Change the economics.</h2></div><p>Report sales are estimates. Every cost, margin, financing term and ramp input is hypothetical. The lottery rate is anchored to a verified statutory minimum, not a project contract.</p></div><form id="assumptions"><div class="toolbar"><div>{field('report_scenario')}</div><div>{field('scope')}</div><button type="button" id="reset-inputs">Restore reference inputs</button></div><p id="input-error" class="error" role="alert" hidden></p><p id="change-count" class="input-note">Reference inputs are loaded.</p>{''.join(group(*g) for g in groups)}<p class="input-note" id="fuel-volume-note">Fuel uses the report gallons. Traffic inputs do not affect this mode.</p></form><div class="actionbar"><button class="primary" id="export-inputs" type="button">Download current inputs (JSON)</button><button id="export-memo" type="button">Download scenario memo</button></div><details><summary>Import saved assumptions</summary><div><label for="import-inputs">Choose an inputs JSON exported by this tool</label><input type="file" id="import-inputs" accept=".json,application/json"><p class="input-note">The file is read locally. Inputs are not uploaded, tracked or saved automatically.</p></div></details><noscript><p class="error">JavaScript is required for recalculation. The reference results, report and downloadable evidence remain usable.</p></noscript></section>
<section class="section" id="cashflow"><p class="eyebrow">03 / From receipts to a financing decision</p><div class="section-head"><h2>Follow the cash.</h2><p>These visuals combine report estimates with the current hypothetical inputs. They are not observed financial statements.</p></div><div class="split"><div><h3 class="chart-title">Monthly receipts are not operating cash.</h3><figure class="chart"><div id="cash-chart">{svg('receipts-to-cash')}</div><figcaption>Lottery proceeds are separated from retailer commission. Contribution includes fuel and all modeled sales categories, after assumed variable costs. Cash available also deducts staffing, overhead and maintenance reserves.</figcaption></figure><details><summary>Inspect the monthly reconciliation</summary><div class="scroll" role="region" aria-label="Monthly cash reconciliation" tabindex="0"><table><thead><tr><th scope="col">Component</th><th scope="col">USD / month</th></tr></thead><tbody id="bridge-body">{''.join('<tr><td>'+esc(k)+'</td><td class="number">'+money(v)+'</td></tr>' for k,v in s['bridge'])}</tbody></table></div></details></div><aside><h3>What would meet the coverage target?</h3><ul class="threshold-list"><li><strong id="capacity-value">{money(s['maximum_supported_eligible_budget'])}</strong>Eligible project-budget ceiling under the stabilized financing screen. Excludes fees, carry, development interest and working capital. This is borrowing capacity at assumed leverage, not fair value.</li><li><strong id="fuel-threshold">{s['required_fuel_gallons']:,.0f} gallons / month</strong>Required fuel volume holding nonfuel contribution fixed. The traffic or capacity needed to support this is not verified.</li><li><strong id="sales-threshold">{s['required_sales_multiplier']*100:.1f}% of selected report case</strong>Required all-sales level with current margins, staffing and financing. Fixed staffing may not support this volume in reality.</li></ul></aside></div><h3>Where the screen changes</h3><div class="legend"><span class="below">Below 0.75x</span><span>Below target</span><span class="above">Meets selected stabilized target</span></div><figure class="chart"><div id="grid-chart">{svg('coverage-frontier')}</div><figcaption>Vary all sales together and core construction input before contingency. All other current assumptions stay fixed. Each cell is an arithmetic scenario, not a likelihood or confidence interval.</figcaption></figure><button type="button" id="export-grid">Download the current coverage grid</button><h3>Does adding a wash improve the illustration?</h3><p class="input-note">The wash adds assumed sales, construction, staffing and maintenance. It is absent from the original revenue table. Core-first does not assign value to a future wash option or guarantee that either scope fits.</p><div class="scroll" role="region" aria-label="Scope comparison" tabindex="0"><table class="scope-table"><thead><tr><th scope="col">Scope</th><th scope="col">Eligible budget</th><th scope="col">Stabilized coverage</th><th scope="col">Year 1 coverage</th><th scope="col">Peak sponsor funding</th></tr></thead><tbody id="scope-body"></tbody></table></div><h3>Draws, delay and the opening ramp</h3><figure class="chart"><div id="funding-chart">{svg('sponsor-funding')}</div><figcaption>The current scenario’s sponsor funding path includes equity-funded fees, interest on staged construction draws, pre-opening carry, opening inventory/working capital and operating deficits. Cash surpluses reduce cumulative net funding. Peak funding is measured only through 36 operating months.</figcaption></figure><p class="input-note">Opening: <strong id="opening-value">Month {r['opening_month']}</strong>. Additional operating-deficit funding beyond opening working capital: <strong id="ramp-funding">{money(r['operating_deficit_funding_36m'])}</strong>.</p><details><summary>Opening-year monthly cash flow</summary><div class="scroll" role="region" aria-label="Opening year cash flow" tabindex="0"><table><thead><tr><th scope="col">Operating month</th><th scope="col">Sales ramp</th><th scope="col">Cash before debt</th><th scope="col">Debt service</th><th scope="col">Cash after debt</th></tr></thead><tbody id="cashflow-body"></tbody></table></div></details><div class="actionbar"><button type="button" id="export-flow">Download all monthly cash flows (CSV)</button></div></section>
<section class="section" id="evidence"><p class="eyebrow">04 / What is known, estimated or missing</p><h2>The evidence has limits.</h2><p class="input-note">The sales totals reconcile. The investment conclusion still depends on missing project-specific evidence and untested operating assumptions.</p>{report_rows}<details open><summary>Eight unresolved decision gates</summary>{gate_rows}</details><details><summary>Four risk classifications fail the report’s own rules</summary>{mismatch_rows}<p class="input-note">R01 thresholds: 1-7 low, 8-14 medium, 15-19 high, 20-25 critical. These labels correct arithmetic consistency only. Subjective likelihood and impact scores are not calibrated probabilities.</p></details><details><summary>Source notes, provenance and anonymization</summary><div>{source_text}</div></details></section><section class="section" id="methods"><p class="eyebrow">05 / Reproduce and challenge the model</p><h2>Methods before certainty.</h2>{methods}<p><a href="report.html">Read the fixed reference report</a> · <a href="scenario_comparison.csv">24 reference scenario combinations</a> · <a href="risk_register_audit.csv">31-risk audit</a> · <a href="sql_reconciliation.csv">SQL reconciliation</a> · <a href="../README.md">Reproduction instructions</a></p></section></main>'''
 footer='<footer class="footer"><p>Independent analytical project by Prathamesh Singh. Anonymized source estimates from April 2026; external references checked 28 October 2026. Original reports and identifying information are not distributed. This is a scenario tool, not an appraisal, engineering certification, legal conclusion or financing commitment.</p></footer></div>'
 data={'defaults':DEFAULT,'report':REPORT};scripts='<script type="application/json" id="project-data">'+json.dumps(data).replace('<','\\u003c')+'</script><script>'+(OUT/'model.js').read_text()+'\n'+(OUT/'app.js').read_text()+'</script>'
 (OUT/'workbench.html').write_text(basehead+body+footer+scripts+'</body></html>')
 # Fixed research report with the exact reproduced reference results.
 mismatches=sum(x['mismatch'] for x in risks)
 reference_comparison=list(csv.DictReader((OUT/'scenario_comparison.csv').open()))
 comparison=table(['Sales case','Scope','Stabilized coverage','Year 1 coverage','Peak sponsor funding'],[(x['report_case'],x['scope'],f'{float(x["stabilized_dscr"]):.2f}x',f'{float(x["year1_dscr"]):.2f}x',money(float(x['peak_sponsor_funding_36m']))) for x in reference_comparison if x['delay_months']=='0'])
 reportbody=f'''<main id="main" class="report-body"><section class="hero" style="display:block"><p class="eyebrow">Reference analysis / Finance and development risk</p><h1>What the sales estimate leaves unanswered.</h1><p class="lead">The reported receipts add up. Whether they support a development budget depends on margins, operating costs, debt terms and the evidence still missing.</p><p><a href="workbench.html">Open the interactive decision lab ↗</a></p></section><p class="badge">All financial results below are hypothetical illustrations.</p><h2>The reference finding</h2><p>Using the report’s average sales estimates, an assumed {money(s['eligible_budget'])} eligible core project budget, 70% debt funding, 8.5% fixed annual interest and 20-year amortization, stabilized coverage is <strong>{ratio(s['dscr'])}</strong>. Cash available is {money(s['cfads'])} per month against {money(s['monthly_debt_service'])} of debt service. The six-month sales ramp lowers opening-year coverage to <strong>{ratio(r['year1_dscr'])}</strong>.</p><p>These results do not establish that the actual development is unviable. No actual budget, loan terms, operating history or complete underlying feasibility data were provided. Eight site-specific evidence gates remain unresolved.</p><figure class="chart">{svg('receipts-to-cash')}<figcaption>Reference report sales plus hypothetical economics. Retained nonfuel receipts are not gross profit. All-category contribution includes assumed net fuel contribution.</figcaption></figure><h2>What reconciles, and what does not</h2><p>All three source nonfuel receipt totals reconcile to their listed categories. The source fuel row provides gallons rather than the dollar contribution suggested by its heading. The average lottery estimate is {money(s['lottery_ticket_sales'])} in face-value ticket sales under our interpretation. At a 5% commission assumption it yields {money(s['lottery_commission'])} of retailer commission. Bonus income is excluded.</p>{report_rows}<p>The report’s 3% capture assumption, 10,200 daily vehicles and 44,154 monthly gallons imply about 4.74 gallons per captured transaction using 365/12 days. If only half of passing traffic is accessible, the equivalent purchase becomes about 9.49 gallons. These are reverse calculations, not validation of demand.</p><p>Population-weighting the three reported block-group median incomes gives approximately $62,895, but this does not establish a combined trade-area median. The demographic estimates lack a source year and margins of error. Demographics alone do not validate demand or the claim that an income mix provides a financial hedge.</p><h2>Scope and financing</h2>{comparison}<p>The wash case introduces hypothetical incremental sales, labor, maintenance and capital. No wash revenue was supplied in the original table. Scope comparisons are conditional on those new inputs, and neither case establishes physical site fit.</p><figure class="chart">{svg('coverage-frontier')}<figcaption>Reference financing assumptions, with core hard cost and all-sales multiplier varied. The contour marks 1.25x stabilized coverage. There is no probability assigned to a cell.</figcaption></figure><p>At the reference operating contribution and leverage, the stabilized financing-capacity ceiling for eligible project cost is {money(s['maximum_supported_eligible_budget'])}, compared with the assumed {money(s['eligible_budget'])} budget. This excludes fees, development interest, carry and working capital. It is a credit screen, not valuation or an acquisition price recommendation.</p><h2>Development funding and delay</h2><p>The reference path requires {money(r['equity_at_opening'])} of sponsor funding through opening and reaches {money(r['peak_sponsor_funding_36m'])} through 36 operating months. Opening inventory and working capital exclude the operating loss reserve. Additional operating deficits require {money(r['operating_deficit_funding_36m'])} over that horizon.</p><figure class="chart">{svg('sponsor-funding')}<figcaption>The delay scenario postpones construction draws and opening. It adds interest only on amounts actually drawn plus explicit carry; it does not assume the entire loan was outstanding from day one. Lost sales are not separately added as a second cash expense.</figcaption></figure><h2>Which inputs deserve the next evidence dollar?</h2><figure class="chart">{svg('coverage-sensitivity')}<figcaption>Prespecified one-at-a-time ranges. These are scenario ranges, not statistical uncertainty bounds. See the sensitivity CSV for exact endpoints.</figcaption></figure><p>First obtain a civil site plan, access evidence, a scope-matched contractor budget and lender terms. Clarify sales categories and obtain documented gross margins and staffing coverage. Those inputs can change the screen more directly than polishing the original risk colors.</p><h2>The risk register needs reconciliation</h2><p>{mismatches} of 31 register classifications conflict with the report’s stated thresholds. The heat map and domain summary also disagree with some register entries. A single domain score has no documented aggregation rule, so this project does not average ordinal ratings or calculate a portfolio risk probability.</p>{mismatch_rows}<p>Residual risk reductions are assertions, not measured outcomes. Planning a mitigation does not establish that it was executed or that its effect is known.</p><h2>Evidence gates</h2>{gate_rows}<h2>Sources and scope of verification</h2>{source_text}<h2>Methods and limitations</h2>{methods}<h2>Reproduce the findings</h2><p>Run <code>python analyze.py</code>, <code>python build_review.py</code>, the Python tests and Node parity checks from the project directory. Analysis is offline and uses sanitized extracts and explicit scenario inputs. The original documents are not bundled.</p><p><a href="reference_monthly_cash_flow.csv">Reference monthly cash flow</a> · <a href="scenario_comparison.csv">Scenario comparisons</a> · <a href="one_at_a_time_sensitivity.csv">Sensitivity inputs</a> · <a href="coverage_frontier.csv">Coverage grid</a> · <a href="risk_register_audit.csv">Risk audit</a> · <a href="sql_reconciliation.csv">SQL reconciliation</a> · <a href="summary.json">Summary results</a> · <a href="../README.md">Project documentation</a></p></main>'''
 (OUT/'report.html').write_text(basehead+reportbody+footer+'</body></html>')
 assert all('\u2014' not in (OUT/f).read_text() for f in ['workbench.html','report.html'])
 print('Built self-contained workbench and reference report')
if __name__=='__main__':main()
